fn largest_smallest_integers(arr: Vec<i8>) -> (Option<i8>, Option<i8>) {
    if arr.is_empty() {
        return (None, None);
    }
    
    let mut max = i8::MIN;
    let mut min = i8::MAX;
    
    for &num in &arr {
        if num > max {
            max = num;
        }
        if num < min {
            min = num;
        }
    }
    
    (Some(max), Some(min))
}